import { randomUUID } from "node:crypto";
import { describe, expect, it } from "vitest";
import {
  resetLocalData,
  requireLocalResetUrl,
} from "../scripts/lib/reset-local-data";
import {
  createIsolatedDatabase,
  databaseTestsEnabled,
} from "./helpers/foundation-db";

describe("local reset destination", () => {
  it("rejects remote, production and overriding connection parameters", () => {
    for (const env of [
      { DATABASE_URL: "postgresql://localhost:5433/mailloop?host=remote" },
      { DATABASE_URL: "postgresql://remote:5433/mailloop" },
      { DATABASE_URL: "postgresql://localhost:5433/other" },
      {
        DATABASE_URL: "postgresql://localhost:5433/mailloop",
        NODE_ENV: "production",
      },
    ])
      expect(() => requireLocalResetUrl(env)).toThrow();
    expect(
      requireLocalResetUrl({
        DATABASE_URL: "postgresql://localhost:5433/mailloop",
      }),
    ).toBe("postgresql://localhost:5433/mailloop");
  });
});

describe.runIf(databaseTestsEnabled)("local data reset", () => {
  it("preserves configured limits, checkout, binding and migrations, and restores audit protection", async () => {
    const fixture = await createIsolatedDatabase();
    try {
      for (const name of fixture.migrations) await fixture.apply(name);
      await fixture.client.query(
        `CREATE TABLE "_prisma_migrations" (id text); INSERT INTO "_prisma_migrations" VALUES ('keep')`,
      );
      await fixture.client.query(
        `UPDATE "SystemControl" SET "paidGatingEnabled"=true,"billingCheckoutEnabled"=true,"dodoEnvironment"='test_mode',"dodoBusinessId"='test-business',"usageCutoverAt"=now() WHERE key='global'`,
      );
      const before = (
        await fixture.client.query(`SELECT * FROM "SystemControl"`)
      ).rows;
      await fixture.client.query(
        `INSERT INTO "User" (id,email) VALUES ($1,'[REDACTED_EMAIL]')`,
        [randomUUID()],
      );
      await resetLocalData(fixture.client, false);
      expect(
        (
          await fixture.client.query(
            `SELECT count(*)::int AS count FROM "User"`,
          )
        ).rows[0].count,
      ).toBe(1);
      await resetLocalData(fixture.client, true);
      expect(
        (
          await fixture.client.query(
            `SELECT count(*)::int AS count FROM "User"`,
          )
        ).rows[0].count,
      ).toBe(0);
      expect(
        (await fixture.client.query(`SELECT * FROM "SystemControl"`)).rows,
      ).toEqual(before);
      expect(
        (await fixture.client.query(`SELECT * FROM "_prisma_migrations"`)).rows,
      ).toEqual([{ id: "keep" }]);
      await expect(
        fixture.client.query(`TRUNCATE "AdminAuditLog"`),
      ).rejects.toMatchObject({ code: "P0001" });
      await fixture.client.query(`DELETE FROM "SystemControl"`);
      await fixture.client.query(
        `INSERT INTO "User" (id,email) VALUES ($1,'[REDACTED_EMAIL]')`,
        [randomUUID()],
      );
      await expect(resetLocalData(fixture.client, true)).rejects.toThrow(
        "Required global system settings",
      );
      expect(
        (
          await fixture.client.query(
            `SELECT count(*)::int AS count FROM "User"`,
          )
        ).rows[0].count,
      ).toBe(1);
    } finally {
      await fixture.cleanup();
    }
  });
});
